let data, view='overview', pageFilter='all', selectedShotId, selectedSceneId, readingScene=false, stalePreviewApproved=false, assetStatus={}, assetFilter='all', assetCheck=0, watching=false, liveStills={}, flow=null, closedLevels=new Set(), flowSeen={}, flowTimer=null, gameFrame='phone';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shots=()=>data.story.episodes.flatMap(e=>e.chapters.flatMap(c=>c.scenes.flatMap(s=>s.shots)));
const toast=t=>{const el=$('#toast');el.textContent=t;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),2500)};
const STATIC=document.documentElement.hasAttribute('data-gf-static');
const PROJECT=STATIC?'data.json':'/gf/api/project';
const HOME=STATIC?new URL('./',location.href).href:location.origin+'/gf/';
const GAME=STATIC?new URL('../',location.href).href:location.origin+'/';
function gameHref(src){if(STATIC&&src==='/')return GAME+'index.html';if(src.startsWith('//'))return new URL(src,location.href).href;if(STATIC&&src.startsWith('/gameflow/previews/'))return HOME+src.slice('/gameflow/'.length);return new URL(src.replace(/^\//,''),GAME).href}
async function api(url,options){const r=await fetch(url,{headers:{'content-type':'application/json'},...(STATIC?{cache:'no-store'}:{}),...options});const out=await r.json();if(!r.ok)throw new Error(out.error+(out.details?'\n'+out.details.join('\n'):''));return out}
const dataStamp=d=>JSON.stringify([d.revision,d.connection,d.evaluation,d.catalogError,d.overview,d.plan,d.design]);
function applyData(next){data=next;assetStatus={};liveStills={};$('#dataChanged').classList.add('hidden');render();checkAssets()}
async function load(){try{applyData(await api(PROJECT))}catch(e){$('#content').innerHTML=`<div class="panel"><h2>Could not load project</h2><p>${esc(e.message)}</p></div>`}}
function busy(){return view==='preview'||!!flow||[...document.querySelectorAll('audio,video')].some(m=>!m.paused)}
async function watchData(){if(watching||!data||document.hidden)return;watching=true;try{const next=await api(PROJECT);if(dataStamp(next)!==dataStamp(data)){if(busy())$('#dataChanged').classList.remove('hidden');else applyData(next)}}catch{}watching=false}
function syncUI(){$('#openGame').href=gameHref(data.project.playableUrl||'/');$('#kitVersion').textContent=`Catalog v${data.kitVersion||'unknown'}${STATIC?' · Saved copy':''}`;const stale=data.syncStatus.stale;$('#syncDot').classList.toggle('stale',stale);$('#syncText').textContent=data.project.name||'Untitled game';$('#banner').classList.toggle('hidden',!stale);if(stale)$('#bannerText').textContent=data.syncStatus.sources.filter(s=>s.status!=='current').map(s=>`${s.path} is ${s.status}`).join(' · ')}
function header(title,count,action=''){return `<div class="toolbar compact-heading"><h1>${esc(title)}${count===undefined||count===''?'':` <small class="muted">${esc(count)}</small>`}</h1>${action}</div>`}
const ICON={play:'<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M7 4.5v15l12-7.5Z"/></svg>',pause:'<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M6.5 4.5h4v15h-4ZM13.5 4.5h4v15h-4Z"/></svg>',back:'<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M18 4.5v15L8 12ZM5.5 4.5h2.5v15H5.5Z"/></svg>',next:'<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M6 4.5v15L16 12ZM16 4.5h2.5v15H16Z"/></svg>',restart:'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12a8 8 0 1 0 2.5-5.8M4 4v5h5"/></svg>'};
const LEVELS={episode:'Episode',chapter:'Chapter',scene:'Scene',shot:'Shot'};
const levelName=level=>data.story.levelNames?.[level]||LEVELS[level];
function plural(word){return /[^aeiou]y$/i.test(word)?word.slice(0,-1)+'ies':/(s|x|ch|sh)$/i.test(word)?word+'es':word+'s'}
function minutes(value){return value>=60?`${Math.floor(value/60)} h${value%60?` ${value%60} min`:''}`:`${value} min`}
function storyRows(){const eps=data.story.episodes,chapters=eps.flatMap(e=>e.chapters),scenes=chapters.flatMap(c=>c.scenes),all=scenes.flatMap(s=>s.shots);return [['episode',eps],['chapter',chapters],['scene',scenes],['shot',all]].filter(([level,items])=>items.length&&(level==='shot'||items.some(x=>x.title))).map(([level,items])=>`${items.length} ${items.length===1?levelName(level):plural(levelName(level))}`)}
function storyCounts(){const rows=storyRows();return `<p class="muted story-counts">${esc(rows.join(' · ')||'No story mapped')} · Expected play: ${data.story.expectedMinutes!==undefined?esc(minutes(data.story.expectedMinutes)):'not given by the game team'}</p>`}
function levelTimes(levels){const rows=levels.filter(([x])=>x?.expectedMinutes!==undefined).map(([x,level])=>`${levelTitle(x)||levelName(level)}: ${minutes(x.expectedMinutes)}`);return rows.length?`<div class="chips shot-flags">${rows.map(r=>`<span class="chip">${esc(r)}</span>`).join('')}</div>`:''}
const assetItems=()=>data.assets?.items||[];
const failedAssets=()=>assetItems().filter(a=>assetStatus[a.id]==='failed');
function updateCount(){const count=(data.unmapped?.items||[]).filter(u=>u.kind==='missing-asset').length+failedAssets().length;$('#unmappedCount').textContent=count;$('#unmappedCount').classList.toggle('hidden',!count)}
function assetUrl(a){try{const url=new URL(gameHref(a.src));return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}}
const is3dFile=a=>a.type==='3d'&&/\.(glb|gltf)(\?|$)/i.test(a.src||'');
const isLive=a=>a.type==='live'||is3dFile(a);
function liveUrl(a){return is3dFile(a)?`${HOME}model-view.html?src=${encodeURIComponent(assetUrl(a))}`:assetUrl(a)}
function probeLive(a){return new Promise(resolve=>{const url=new URL(liveUrl(a)||gameHref('/'));url.searchParams.set('gfStill','1');const frame=document.createElement('iframe');frame.className='live-probe';frame.title='Rendering preview';frame.setAttribute('aria-hidden','true');const finish=status=>{clearTimeout(timer);window.removeEventListener('message',listen);frame.remove();resolve(status)};const listen=e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin||!e.data?.gameflowPreview)return;if(e.data.gameflowPreview==='ready'){if(typeof e.data.image==='string'&&e.data.image.startsWith('data:image/'))liveStills[a.id]=e.data.image;finish('loaded')}else finish('failed')};const timer=setTimeout(()=>finish('failed'),30000);window.addEventListener('message',listen);frame.src=url.href;document.body.append(frame)})}
function probeAsset(a){return new Promise(resolve=>{const src=assetUrl(a);if(!src)return resolve('failed');const finish=status=>{clearTimeout(timer);resolve(status)};const timer=setTimeout(()=>finish('failed'),20000);
 if(a.type==='image'){const img=new Image();img.onload=()=>finish('loaded');img.onerror=()=>finish('failed');img.src=src;return}
 if(a.type==='audio'||a.type==='video'){const media=document.createElement(a.type);media.preload='metadata';media.onloadedmetadata=()=>finish('loaded');media.onerror=()=>finish('failed');media.src=src;return}
 fetch(src).then(r=>{r.body?.cancel();finish(r.ok&&!(r.headers.get('content-type')||'').includes('text/html')?'loaded':'failed')},()=>finish('failed'))})}
async function drainAssets(queue,workers,probe,run){await Promise.all(Array.from({length:workers},async()=>{while(queue.length){const a=queue.shift();const status=await probe(a);if(run!==assetCheck)return;assetStatus[a.id]=status;updateAssetStatus()}}))}
async function checkAssets(){const run=++assetCheck;for(const a of assetItems())if(a.type==='code')assetStatus[a.id]='code';await Promise.all([drainAssets(assetItems().filter(a=>a.type!=='code'&&!isLive(a)),6,probeAsset,run),drainAssets(assetItems().filter(isLive),2,probeLive,run)]);if(run===assetCheck&&view==='unmapped'&&data.connection?.state!=='error')renderUnmapped()}
const statusLabel=id=>({loaded:'Loaded',failed:'Failed to load',code:'Built in code'}[assetStatus[id]]||'Checking…');
function updateAssetStatus(){updateCount();document.querySelectorAll('[data-asset-status]').forEach(el=>{const id=el.dataset.assetStatus;el.textContent=statusLabel(id);el.classList.toggle('failed',assetStatus[id]==='failed')});document.querySelectorAll('.live-preview:not([data-open])').forEach(el=>{const a=assetItems().find(x=>x.id===el.dataset.live);if(a)el.innerHTML=liveInner(a)});document.querySelectorAll('img[data-still]').forEach(img=>{const still=liveStills[img.dataset.still];if(still&&img.getAttribute('src')!==still){img.src=still;img.classList.remove('hidden')}});if($('#assetSummary'))$('#assetSummary').textContent=assetSummary()}
function assetSummary(){const all=assetItems(),loaded=all.filter(a=>assetStatus[a.id]==='loaded').length,failed=failedAssets().length,code=all.filter(a=>assetStatus[a.id]==='code').length,waiting=all.length-loaded-failed-code;return `${loaded} loaded · ${failed} failed${code?` · ${code} no preview`:''}${waiting?` · ${waiting} checking`:''}`}
function liveInner(a){const still=liveStills[a.id],status=assetStatus[a.id];return `${still?`<img src="${esc(still)}" alt="${esc(a.name||a.id)}">`:`<div class="asset-file">${status==='failed'?'Preview failed to load':status==='loaded'?'Live preview ready':'Rendering preview…'}</div>`}${status==='failed'?'':'<button class="btn live-open" data-open-live>Open 3D</button>'}`}
function assetPreview(a){if(isLive(a))return `<div class="live-preview" data-live="${esc(a.id)}">${liveInner(a)}</div>`;if(a.type==='code')return `<div class="asset-file">Built in code · no preview${a.reason?`<br>${esc(a.reason)}`:''}</div>`;const src=esc(assetUrl(a));if(a.type==='image')return `<img loading="lazy" src="${src}" alt="${esc(a.name||a.id)}">`;if(a.type==='audio')return `<audio controls preload="none" src="${src}"></audio>`;if(a.type==='video')return `<video controls preload="metadata" src="${src}"></video>`;return `<div class="asset-file">${a.type==='3d'?'3D file':'File'} · preview unavailable</div>`}
function linkedAssets(ids){return (ids||[]).map(id=>assetItems().find(a=>a.id===id)).filter(Boolean).map(a=>`<div class="linked-asset">${assetPreview(a)}${isLive(a)||a.type==='image'?'':`<small class="muted">${esc(a.name||a.id)}</small>`}</div>`).join('')}
function visualOf(x){return (x?.assetIds||[]).map(id=>assetItems().find(a=>a.id===id)).find(a=>a&&(a.type==='image'||isLive(a)))}
function stillTag(a,alt,cls=''){const src=isLive(a)?liveStills[a.id]:assetUrl(a);return `<img class="${cls}${src?'':' hidden'}" ${isLive(a)?`data-still="${esc(a.id)}"`:''} ${src?`src="${esc(src)}"`:''} alt="${esc(alt)}">`}
function stageVisual(sh){const place=visualOf(data.locations.items.find(l=>l.id===sh.locationId)),cast=(sh.characterIds||[]).map(id=>data.characters.items.find(c=>c.id===id)).map(c=>({c,a:visualOf(c)})).filter(x=>x.a);if(!place&&!cast.length)return '';return `<div class="stage-visual">${place?stillTag(place,setName(sh.locationId),'stage-place'):''}${cast.length?`<div class="stage-cast">${cast.map(x=>stillTag(x.a,x.c.name,'stage-actor')).join('')}</div>`:''}</div><small class="muted stage-note">Location and cast from the game. This is not the rendered shot.</small>`}
function openLive(button){const box=button.closest('.live-preview'),a=assetItems().find(x=>x.id===box.dataset.live);if(!a)return;closeLive();box.dataset.open='1';box.innerHTML=`<iframe src="${esc(liveUrl(a))}" title="${esc(a.name||a.id)}" allow="fullscreen"></iframe><button class="btn live-open" data-close-live>Close</button>`}
function closeLive(){document.querySelectorAll('.live-preview[data-open]').forEach(box=>{delete box.dataset.open;const a=assetItems().find(x=>x.id===box.dataset.live);if(a)box.innerHTML=liveInner(a)})}
function usedBy(id){return [...data.characters.items,...data.locations.items,...shots()].filter(x=>(x.assetIds||[]).includes(id)).map(x=>x.name||x.title||x.id)}
function render(){if(!data)return;updateCount();if(data.connection&&['unconnected','error'].includes(data.connection.state)&&!['settings','preview','review'].includes(view)){renderConnection();return;}$('#content').classList.toggle('preview-content',view==='preview');$('#projectName').textContent=data.project.name;syncUI();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));({pages:renderPages,overview:renderOverview,plan:renderPlan,design:renderDesign,review:renderReview,characters:renderCharacters,locations:renderLocations,staging:renderStaging,styling:renderStyling,preview:renderPreview,assets:renderAssets,sound:renderSound,catalogue:renderCatalogue,unmapped:renderUnmapped,settings:renderSettings}[view])()}
function renderCharacters(){const cards=data.characters.items.map(x=>`<article class="card">${visualOf(x)?'':`<div class="avatar">${esc(x.name.split(/\s/).map(n=>n[0]).join('').slice(0,2))}</div>`}<h3>${esc(x.name)}</h3><div class="muted">${esc(x.role)}</div>${x.playerChosen?'<div class="chips"><span class="chip">Chosen by the player</span></div>':''}<p>${esc(x.description)}</p>${linkedAssets(x.assetIds)}<div class="chips">${(x.assets||[]).map(a=>`<span class="chip">${esc(a)}</span>`).join('')||(x.assetIds?.length?'':'<span class="chip">No linked assets</span>')}</div></article>`).join('');$('#content').innerHTML=header('Characters',data.characters.items.length)+(cards?`<div class="grid">${cards}</div>`:noneYet('No characters','None were reported for this game.'))+catalogueFor('characters')}
function renderLocations(){const cards=data.locations.items.map(x=>`<article class="card"><div class="eyebrow">${esc(x.id)}</div><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p>${linkedAssets(x.assetIds)}<div class="chips">${(x.props||[]).map(p=>`<span class="chip">${esc(p)}</span>`).join('')}</div></article>`).join('');$('#content').innerHTML=header('Locations',data.locations.items.length)+(cards?`<div class="grid">${cards}</div>`:noneYet('No locations','None were reported for this game.'))+catalogueFor('locations')}
function noneYet(title,text){return `<div class="panel"><h2>${esc(title)}</h2><p class="muted">${esc(text)}</p></div>`}
function safeRoute(route){return typeof route==='string'&&route.startsWith('/')&&!route.startsWith('//')}
function catalogueItem(x){return `<article class="card asset-card"><strong>${esc(x.name)}</strong>${x.description?`<p class="muted">${esc(x.description)}</p>`:''}${linkedAssets(x.assetIds)}${detailList(x.details)}<small class="muted asset-path">${[safeRoute(x.route)?pageLink(x.route):'',esc(x.source||'')].filter(Boolean).join(' · ')}</small></article>`}
function catalogueSection(c){return `<section class="asset-group"><h3 class="unmapped-source">${esc(c.title)} <small class="muted">${c.items.length}</small></h3>${c.description?`<p class="muted">${esc(c.description)}</p>`:''}<div class="grid">${c.items.map(catalogueItem).join('')}</div></section>`}
function catalogueFor(browser){return (data.catalogue?.sections||[]).filter(c=>c.browser===browser).map(catalogueSection).join('')}
function detailList(details){return details?.length?`<dl class="detail-list">${details.map(d=>`<div><dt>${esc(d.label)}</dt><dd>${esc(d.value)}</dd></div>`).join('')}</dl>`:''}
function lineBlock(d){return `<div class="spoken-line"><strong>${esc(castNames([d.speakerId])||'Speaker')}</strong>${prose(d.text)}${(d.variants||[]).map(v=>`<p class="line-variant"><span class="muted">If ${esc(v.when)}:</span> ${esc(v.text)}</p>`).join('')}</div>`}
function shotMedia(sh){if(!sh.media?.src)return '';let url;try{url=new URL(gameHref(sh.media.src))}catch{return ''}if(!['http:','https:'].includes(url.protocol))return '';if(sh.media.type==='image')return `<img src="${esc(url.href)}" alt="${esc(shotTitle(sh))}">`;if(sh.media.type==='video')return `<video controls preload="metadata" src="${esc(url.href)}"></video>`;return '<div class="media-empty">3D asset linked · preview unavailable</div>'}
function stagingScenes(){return data.story.episodes.flatMap(ep=>ep.chapters.flatMap(ch=>ch.scenes.map(sc=>({ep,ch,sc}))))}
function tidy(text){return text.replace(/[-_]+/g,' ').replace(/^./,c=>c.toUpperCase())}
const isSlug=text=>/^[a-z0-9]+([-_][a-z0-9]+)*$/.test(text);
function levelTitle(x){return !x?.title?'':isSlug(x.title)?tidy(x.title):x.title}
function shotTitle(sh){const raw=sh?.title||sh?.id||'Shot';if(!isSlug(raw))return raw;const ep=shotContext(sh.id)?.ep.id;return tidy(ep&&raw.startsWith(ep+'-')?raw.slice(ep.length+1):raw)}
function effectText(e){return typeof e==='string'?e:`${e.stat} ${e.change>0?'+':''}${e.change}`}
function timerLine(sh){if(!sh.choiceTimer)return '';const fallback=sh.choices?.find(c=>c.id===sh.choiceTimer.defaultChoiceId)?.label;return `<p class="muted shot-timer">Timed choice: ${esc(sh.choiceTimer.seconds)} s${fallback?` · if no answer: ${esc(fallback)}`:''}</p>`}
function shotFlags(sh){const flags=[sh.minutesSoFar!==undefined?`By here: ${minutes(sh.minutesSoFar)}`:'',sh.expectedMinutes!==undefined?`Expected: ${minutes(sh.expectedMinutes)}`:'',sh.when?`Plays when: ${sh.when}`:'',sh.ending?`Ending: ${sh.ending.kind}${sh.ending.title?' · '+sh.ending.title:''}`:''].filter(Boolean);return flags.length?`<div class="chips shot-flags">${flags.map(f=>`<span class="chip">${esc(f)}</span>`).join('')}</div>`:''}
function tree(){const count=x=>x.chapters?x.chapters.flatMap(c=>c.scenes).flatMap(s=>s.shots).length:x.scenes.flatMap(s=>s.shots).length;const level=(title,inner,x)=>title?`<details data-level="${esc(x.id)}" ${closedLevels.has(x.id)?'':'open'}><summary>${esc(title)} <small class="muted">${count(x)}</small></summary>${inner}</details>`:inner;return data.story.episodes.map(ep=>level(levelTitle(ep),ep.chapters.map(ch=>level(levelTitle(ch),ch.scenes.map(sc=>`<div class="scene-branch">${levelTitle(sc)?`<button data-scene="${esc(sc.id)}" class="${selectedSceneId===sc.id&&!selectedShotId?'active':''}">${esc(levelTitle(sc))} <small>${esc(levelName('scene'))}</small></button>`:''}${sc.shots.map((sh,i)=>`<button data-shot="${esc(sh.id)}" class="${sh.id===selectedShotId?'active':''}"><small>${String(i+1).padStart(2,'0')}</small> ${esc(shotTitle(sh))}</button>`).join('')}</div>`).join(''),ch)).join(''),ep)).join('')}
function prose(text,empty='Not added yet'){return `<p class="reading-text ${text?'':'muted'}">${esc(text||empty)}</p>`}
function castNames(ids){return (ids||[]).map(id=>data.characters.items.find(c=>c.id===id)?.name||id).join(', ')}
function setName(id){return data.locations.items.find(l=>l.id===id)?.name||id||''}
function spokenText(value){return typeof value==='string'?value:Array.isArray(value)?value.map(x=>typeof x==='string'?x:x.text||'').join('\n'):value?.text||''}
function shotBody(sh,media=true){
 const dialogue=(sh.dialogue||[]).map(lineBlock).join('');
 const narration=spokenText(sh.narration);const subtitle=spokenText(sh.subtitles);const spoken=(sh.dialogue||[]).map(d=>d.text).filter(Boolean).concat(narration||[]).join('\n');
 let visual='<div class="media-empty"><span>Shot preview</span><small>No media linked yet</small></div>';
 visual=shotMedia(sh)||stageVisual(sh)||visual;
 const next=(sh.choices||[]).length?sh.choices.map(c=>`<div class="branch-choice"><strong>${esc(c.label)}</strong>${prose(c.consequence,'No consequence described')}${c.effects?.length?`<div class="chips">${c.effects.map(e=>`<span class="chip">${esc(effectText(e))}</span>`).join('')}</div>`:''}<span class="muted">Next: ${esc(shotTitle(shots().find(s=>s.id===c.nextShotId)))}</span></div>`).join(''):prose(sh.nextShotId?shotTitle(shots().find(s=>s.id===sh.nextShotId)):'End of this path');
 return `${media?`<div class="shot-media">${visual}</div>`:''}${shotFlags(sh)}${sh.description?`<div class="reading-card"><h3>Action</h3>${prose(sh.description)}</div>`:''}${sh.onScreenText?.length?`<div class="reading-card"><h3>On-screen text</h3>${sh.onScreenText.map(t=>prose(t)).join('')}</div>`:''}<div class="reading-card"><h3>Dialogue</h3>${dialogue||prose('', 'No dialogue · this shot can be silent')}</div>${sh.assetIds?.length?`<div class="reading-card"><h3>Linked assets</h3>${linkedAssets(sh.assetIds)}</div>`:''}<div class="reading-card"><h3>Narration</h3>${prose(narration,'No narration')}</div><div class="reading-card"><h3>Subtitles <small>${subtitle&&subtitle!==spoken?'Custom text':'Follow speech'}</small></h3>${prose(subtitle||spoken,'No spoken text to subtitle')}</div><div class="reading-card"><h3>Cast & set</h3><div class="row"><div><span class="eyebrow">Cast</span>${prose(castNames(sh.characterIds),'No cast linked')}</div><div><span class="eyebrow">Set</span>${prose(setName(sh.locationId),'No set linked')}</div></div></div>${sh.details?.length||sh.durationMs?`<div class="reading-card"><h3>Details</h3>${detailList([...(sh.durationMs?[{label:'Duration',value:(sh.durationMs/1000).toFixed(1)+' s'}]:[]),...(sh.details||[])])}</div>`:''}<div class="reading-card"><h3>Next</h3>${timerLine(sh)}${next}</div>`;
}
function renderStaging(){
 if(flow&&shots().some(s=>s.id===flow.current))return renderFlow();flow=null;
 const scenes=stagingScenes();let context=selectedShotId?scenes.find(x=>x.sc.shots.some(s=>s.id===selectedShotId)):scenes.find(x=>x.sc.id===selectedSceneId);context=context||scenes[0];
 if(!context){$('#content').innerHTML=header('Story')+'<div class="panel"><h2>No story mapped</h2><p class="muted">That is fine if this game has no story. Everything else is on the other pages.</p></div>';return}
 const {ep,ch,sc}=context;selectedSceneId=sc.id;const sh=sc.shots.find(s=>s.id===selectedShotId);if(!sh)selectedShotId=null;
 const cast=[...new Set([...(sc.characterIds||[]),...sc.shots.flatMap(s=>s.characterIds||[])])];const sets=[...new Set([sc.locationId,...sc.shots.map(s=>s.locationId)].filter(Boolean))];
 let body;
 if(readingScene){body=`<div class="detail-heading"><div><span class="eyebrow">${esc(levelName('scene'))} script · ${sc.shots.length} ${esc(plural(levelName('shot')))}</span><h2>${esc(levelTitle(sc)||'Scene')}</h2></div><button class="btn" id="sceneBack">Back to ${esc(levelName('scene').toLowerCase())}</button></div>${prose(sc.story,'No summary yet')}${sc.shots.map((s,i)=>`<article class="scene-script-shot"><span class="eyebrow">${esc(levelName('shot'))} ${i+1}</span><h2>${esc(shotTitle(s))}</h2>${shotBody(s,false)}</article>`).join('')||prose('','No shots yet')}`}
 else if(sh){body=`<div class="detail-heading"><div><span class="eyebrow">${esc(levelName('shot'))} ${sc.shots.indexOf(sh)+1} / ${sc.shots.length}</span><h2>${esc(shotTitle(sh))}</h2></div><button class="btn" id="readScene">Read ${esc(levelName('scene').toLowerCase())}</button></div>${shotBody(sh)}`}
 else{body=`<div class="detail-heading"><div><span class="eyebrow">${esc(levelName('scene'))} overview</span><h2>${esc(levelTitle(sc)||'Scene')}</h2></div><button class="btn" id="readScene">Read ${esc(levelName('scene').toLowerCase())}</button></div><div class="reading-card"><h3>Story summary</h3>${prose(sc.story)}</div><div class="reading-card"><h3>Setting</h3>${prose(sets.map(setName).join(', '),'No set linked')}</div><div class="reading-card"><h3>Cast</h3>${prose(castNames(cast),'No cast linked')}</div><div class="reading-card"><h3>${esc(levelName('shot'))} sequence</h3>${sc.shots.map((s,i)=>`<button class="sequence-shot" data-shot="${esc(s.id)}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(shotTitle(s))}</strong><p>${esc(s.description||s.onScreenText?.[0]||s.dialogue?.[0]?.text||spokenText(s.narration)||'')}</p></div><span>→</span></button>`).join('')||prose('',`No ${plural(levelName('shot')).toLowerCase()} yet`)}</div>${ep.story||ch.story?`<details class="reading-card"><summary>Episode & chapter context</summary>${prose(ep.story,'No episode summary')}${prose(ch.story,'No chapter summary')}</details>`:''}`}
 const playable=data.flow?.find(f=>f.id===ep.id)?.entryShotId,treeTop=$('.tree')?.scrollTop||0;$('#content').innerHTML=header('Story','',playable?`<button class="btn primary icon-btn" id="playEpisode" title="Play ${esc(levelTitle(ep)||'story')}">${ICON.play}Play</button>`:'')+storyCounts()+`<div class="stagegrid"><aside class="panel tree"><div class="eyebrow">Story</div>${tree()}</aside><section class="staging-detail"><div class="breadcrumbs">${[ep,ch,sc].map(levelTitle).filter(Boolean).map(esc).join(' / ')}</div>${levelTimes([[ep,'episode'],[ch,'chapter'],[sc,'scene']])}${body}</section></div>`;
 if($('.tree'))$('.tree').scrollTop=treeTop;document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{selectedSceneId=b.dataset.scene;selectedShotId=null;readingScene=false;renderStaging()});document.querySelectorAll('[data-shot]').forEach(b=>b.onclick=()=>{selectedShotId=b.dataset.shot;readingScene=false;renderStaging()});if($('#playEpisode'))$('#playEpisode').onclick=()=>startFlow(ep.id);if($('#readScene'))$('#readScene').onclick=()=>{readingScene=true;renderStaging()};if($('#sceneBack'))$('#sceneBack').onclick=()=>{readingScene=false;selectedShotId=null;renderStaging()};
}
function uiPreview(src){if(!safeRoute(src))return '';const url=gameHref(src);return /\.(png|jpe?g|gif|webp|avif|svg)$/i.test(src)?`<img loading="lazy" class="ui-preview" src="${esc(url)}" alt="UI preview">`:`<iframe loading="lazy" class="ui-preview" src="${esc(url)}" title="UI preview"></iframe>`}
function renderStyling(){const mocks=(data.ui?.mocks||[]).map(m=>({name:m.name||m.id,description:m.description,src:m.previewSrc,status:m.status||'pending',source:m.target})),pages=(data.pages?.items||[]).filter(p=>/mock|ui/i.test(p.kind)).map(p=>({name:p.name,description:'',src:p.route,status:p.status,source:p.source})),items=[...mocks,...pages],extra=catalogueFor('ui');$('#content').innerHTML=header('UI',items.length)+(items.length?`<p class="muted">${items.length} UI ${items.length===1?'tryout':'tryouts'}</p><div class="grid">${items.map(m=>`<article class="card asset-card">${uiPreview(m.src)}<strong>${esc(m.name)}</strong>${m.description?`<p class="muted">${esc(m.description)}</p>`:''}<small class="muted asset-path">${[pageLink(m.src),esc(m.source||'')].filter(Boolean).join(' · ')}</small>${m.status?`<div class="chips"><span class="chip">${esc(m.status)}</span></div>`:''}</article>`).join('')}</div>`:extra?'':noneYet('No UI tryouts','None were reported for this game.'))+extra}
function renderCatalogue(){const all=data.catalogue?.sections||[],sections=all.filter(c=>!c.browser),absent=(data.standardSections||[]).filter(x=>!all.some(c=>c.id===x.id));$('#content').innerHTML=header('More from the game',sections.length)+(sections.length?sections.map(catalogueSection).join(''):noneYet('Nothing listed','Nothing else was reported for this game.'))+(absent.length?`<p class="muted catalogue-absent">Not listed for this game: ${absent.map(x=>esc(x.title)).join(', ')}</p>`:'')}
function renderSound(){const audio=assetItems().filter(a=>a.type==='audio'),groups=[...new Set(audio.map(a=>a.group||'Other'))],extra=catalogueFor('sound'),pages=(data.pages?.items||[]).filter(p=>/audition|sound/i.test(p.kind));$('#content').innerHTML=header('Sound',audio.length)+(audio.length?`<p class="muted">${audio.length} sound ${audio.length===1?'file':'files'}, played live from the game’s own files.</p>${groups.map(g=>`<section class="asset-group"><h3 class="unmapped-source">${esc(g)} <small class="muted">${audio.filter(a=>(a.group||'Other')===g).length}</small></h3><div class="grid">${audio.filter(a=>(a.group||'Other')===g).map(assetCard).join('')}</div></section>`).join('')}`:extra?'':noneYet('No sound files','None were reported for this game.'))+(pages.length?`<section class="asset-group"><h3 class="unmapped-source">Sound pages</h3>${pages.map(p=>unmappedRow(p.name,p.route||p.source||'')).join('')}</section>`:'')+extra}
function shotContext(id){for(const ep of data.story.episodes)for(const ch of ep.chapters)for(const sc of ch.scenes){const sh=sc.shots.find(s=>s.id===id);if(sh)return {ep,ch,sc,sh}}}
function stopFlowTimer(){clearTimeout(flowTimer);flowTimer=null}
function startFlow(epId){const info=data.flow.find(f=>f.id===epId);flowSeen[epId]=flowSeen[epId]||new Set();flow={epId,current:info.entryShotId,path:[],playing:false};renderFlow()}
function flowGo(id){flow.path.push(flow.current);flow.current=id;renderFlow()}
function shotTiming(sh){if(sh.durationMs)return {ms:sh.durationMs,estimated:false};const text=[...(sh.dialogue||[]).map(d=>d.text),spokenText(sh.narration),...(sh.onScreenText||[])].join(' ').trim(),words=text?text.split(/\s+/).length:0;return {ms:Math.max(2000,1200+words*400),estimated:true}}
function renderFlow(){stopFlowTimer();const {ep,ch,sc,sh}=shotContext(flow.current),info=data.flow.find(f=>f.id===ep.id),seen=flowSeen[ep.id]=flowSeen[ep.id]||new Set();seen.add(sh.id);const choices=sh.choices||[],ended=!choices.length&&!sh.nextShotId,timing=shotTiming(sh),narration=spokenText(sh.narration),cast=castNames(sh.characterIds),place=setName(sh.locationId),media=shotMedia(sh)||stageVisual(sh);if(ended)flow.playing=false;const endingKinds=[...new Set(info.endings.map(id=>shotContext(id)?.sh.ending?.kind).filter(Boolean))];const seenInEpisode=[...seen].filter(id=>shotContext(id)?.ep.id===ep.id).length;
 const checks=[info.unreachable.length?`<p class="flow-warn">${info.unreachable.length} ${info.unreachable.length===1?'shot has':'shots have'} no path to reach them: ${info.unreachable.map(id=>esc(shotTitle(shotContext(id)?.sh||{id}))).join(', ')}</p>`:'<p class="muted">Every shot can be reached.</p>',`<p class="muted">${info.branches?`${info.branches} ${info.branches===1?'shot has':'shots have'} choices`:'One straight line, with no choices'}</p>`,`<p class="muted">${info.endings.length?`${info.endings.length} ${info.endings.length===1?'ending':'endings'}${endingKinds.length?': '+esc(endingKinds.join(', ')):''}`:'No ending here: it continues'}</p>`,`<p class="muted" id="flowSeen">You have seen ${seenInEpisode} of ${info.shotCount} shots</p>`].join('');
 $('#content').innerHTML=header('Play '+(levelTitle(ep)||'story'),'','<button class="btn" id="flowExit">Back to Story</button>')+storyCounts()+`<div class="stagegrid"><aside class="panel tree flow-side"><div class="eyebrow">Flow check</div>${checks}<div class="eyebrow">Played so far</div><ol class="flow-path">${[...flow.path,flow.current].map((id,i)=>`<li><button data-flow-back="${i}" class="${i===flow.path.length?'active':''}"><small>${String(i+1).padStart(2,'0')}</small> ${esc(shotTitle(shotContext(id)?.sh||{id}))}</button></li>`).join('')}</ol></aside><section class="staging-detail"><div class="breadcrumbs">${[ch,sc].map(levelTitle).filter(Boolean).map(esc).join(' / ')}</div>${levelTimes([[ep,'episode'],[ch,'chapter'],[sc,'scene']])}<div class="flow-screen">${media?`<div class="shot-media">${media}</div>`:''}<span class="eyebrow">${esc(place||'No location')}${cast?' · '+esc(cast):''}</span><h2>${esc(shotTitle(sh))}</h2>${shotFlags(sh)}${sh.description?prose(sh.description):''}${(sh.onScreenText||[]).map(t=>`<p class="flow-onscreen">${esc(t)}</p>`).join('')}${(sh.dialogue||[]).map(lineBlock).join('')}${narration?`<p class="flow-narration">${esc(narration)}</p>`:''}${sh.assetIds?.length?`<div class="flow-voice">${linkedAssets(sh.assetIds)}</div>`:''}${timerLine(sh)}${choices.length?`<div class="flow-choices">${choices.map(c=>`<button class="btn" data-flow-next="${esc(c.nextShotId)}"><strong>${esc(c.label)}</strong>${c.consequence?`<small class="muted">${esc(c.consequence)}</small>`:''}${c.effects?.length?`<small class="muted">${esc(c.effects.map(effectText).join(' · '))}</small>`:''}</button>`).join('')}</div>`:''}${ended?'<p class="flow-end">End of this path.</p>':''}${sh.details?.length?`<details class="flow-details"><summary>Details</summary>${detailList(sh.details)}</details>`:''}</div><div class="flow-controls"><button class="btn icon-btn" id="flowBack" ${flow.path.length?'':'disabled'}>${ICON.back}Back</button><button class="btn primary icon-btn" id="flowPlay" aria-label="${flow.playing?'Pause':'Play'}" ${ended?'disabled':''}>${flow.playing?ICON.pause+'Pause':ICON.play+'Play'}</button><button class="btn icon-btn" id="flowNext" ${sh.nextShotId&&!choices.length?'':'disabled'}>${ICON.next}Next</button><button class="btn icon-btn" id="flowRestart">${ICON.restart}Restart</button><small class="muted">${(timing.ms/1000).toFixed(1)} s${timing.estimated?' · estimated':''}</small></div></section></div>`;
 document.querySelector('.flow-path .active')?.scrollIntoView({block:'nearest'});$('.staging-detail').scrollTop=0;
 $('#flowExit').onclick=()=>{stopFlowTimer();flow=null;renderStaging()};$('#flowBack').onclick=()=>{flow.current=flow.path.pop();flow.playing=false;renderFlow()};$('#flowNext').onclick=()=>flowGo(sh.nextShotId);$('#flowRestart').onclick=()=>{flow.current=data.flow.find(f=>f.id===flow.epId).entryShotId;flow.path=[];flow.playing=false;renderFlow()};$('#flowPlay').onclick=()=>{flow.playing=!flow.playing;renderFlow()};
 document.querySelectorAll('[data-flow-next]').forEach(b=>b.onclick=()=>flowGo(b.dataset.flowNext));document.querySelectorAll('[data-flow-back]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.flowBack);if(i>=flow.path.length)return;flow.current=flow.path[i];flow.path=flow.path.slice(0,i);flow.playing=false;renderFlow()});
 if(flow.playing){document.querySelector('.flow-voice audio')?.play().catch(()=>{});if(sh.nextShotId&&!choices.length)flowTimer=setTimeout(()=>flowGo(sh.nextShotId),timing.ms)}
}
function assetCard(a){const used=usedBy(a.id);return `<article class="card asset-card">${assetPreview(a)}<strong>${esc(a.name||a.id)}</strong><small class="muted asset-path">${esc(a.src||a.source||'')}</small>${used.length?`<small class="muted">Used by ${esc(used.join(', '))}</small>`:a.brand?'':'<small class="muted">Not linked to the story</small>'}<div class="chips"><span class="chip">${esc(a.type)}</span><span class="chip asset-status ${assetStatus[a.id]==='failed'?'failed':''}" data-asset-status="${esc(a.id)}">${statusLabel(a.id)}</span></div></article>`}
// One category at a time: a game can have hundreds of assets. Categories come from each asset's group.
const BRANDING='__branding__',catOf=a=>BRAND[a.brand]?BRANDING:a.group||'Other',catName=c=>c===BRANDING?'Branding':c;
function renderAssets(){const all=assetItems(),cats=[BRANDING,...new Set(all.filter(a=>!BRAND[a.brand]).map(catOf))],count=c=>all.filter(a=>catOf(a)===c).length;if(!cats.includes(assetFilter))assetFilter=cats.find(c=>count(c))||BRANDING;
 const body=assetFilter===BRANDING?brandingSection():`<section class="asset-group"><div class="grid">${all.filter(a=>catOf(a)===assetFilter).map(assetCard).join('')}</div></section>`;
 const none=data.reported?.assets?'<div class="panel"><h2>No assets</h2><p>The assistant reported no asset files in this game.</p></div>':'<div class="panel"><h2>No report yet</h2><p class="muted">This connection has not reported its assets. Ask your coding assistant to add them.</p></div>';
 $('#content').innerHTML=header('Assets',all.length)+(all.length?`<p class="muted" id="assetSummary">${assetSummary()}</p><p class="muted">Loaded live from the game’s own files. Nothing is copied.</p><div class="asset-filters asset-cats">${cats.map(c=>`<button class="${c===assetFilter?'active':''}" data-asset-cat="${esc(c)}">${esc(catName(c))} <small>${count(c)}</small></button>`).join('')}</div>${body}`:none);
 document.querySelectorAll('[data-asset-cat]').forEach(b=>b.onclick=()=>{closeLive();assetFilter=b.dataset.assetCat;renderAssets()})}
function unmappedRow(title,text){return `<div class="unmapped-item"><strong>${esc(title)}</strong><p class="muted">${esc(text)}</p></div>`}
function bySource(items){return [...new Set(items.map(u=>u.source))].map(source=>`<div class="reading-card"><h3 class="unmapped-source">${esc(source)}</h3>${items.filter(u=>u.source===source).map(u=>unmappedRow(u.item,u.reason)).join('')}</div>`).join('')}
function pageLink(route){return route?.startsWith('/')&&!route.startsWith('//')?`<a href="${esc(gameHref(route))}" target="_blank" rel="noopener">${esc(route)}</a>`:esc(route||'')}
function renderUnmapped(){const items=data.unmapped.items,missing=items.filter(u=>u.kind==='missing-asset'),unsupported=items.filter(u=>!['missing-asset','stays-in-game'].includes(u.kind)),stays=items.filter(u=>u.kind==='stays-in-game'),failed=failedAssets();
 const none=(title,text)=>`<div class="panel"><h3>${title}</h3><p class="muted">${text}</p></div>`;
 const noReport=what=>none('No report yet',`This connection has not reported ${what}, so some may be missing here. Ask your coding assistant to add the report.`);
 const missingBody=missing.length||failed.length?bySource(missing)+(failed.length?`<div class="reading-card"><h3>Did not load in this browser</h3>${failed.map(a=>unmappedRow(a.name||a.id,a.src)).join('')}</div>`:''):data.reported?.unmapped?none('Nothing missing','No missing assets were reported, and every listed asset loaded.'):noReport('missing assets');
 const unsupportedBody=unsupported.length?bySource(unsupported):data.reported?.unmapped?none('Nothing here','The assistant reported nothing without a home.'):noReport('unsupported data');
 $('#content').innerHTML=header('Unmapped items')+`<p class="muted">Every game has some leftovers, and that is normal. They stay unchanged in the game’s files. Only missing files count as problems.</p><h2 class="unmapped-title">Missing assets <small class="muted">${missing.length+failed.length}</small></h2>${missingBody}<h2 class="unmapped-title">No home yet <small class="muted">${unsupported.length}</small></h2>${unsupportedBody}${stays.length?`<details class="unmapped-stays"><summary class="unmapped-title">Stays in the game <small class="muted">${stays.length}</small></summary>${bySource(stays)}</details>`:''}<p class="muted unmapped-pages">Every game page, with its link, is on the <button class="text-link" data-go="pages">Pages</button> page.</p>`}
function renderPreview(){$('#content').innerHTML=`<div class="game-bar"><div class="asset-filters"><button data-frame="phone" class="${gameFrame==='phone'?'active':''}">Phone</button><button data-frame="wide" class="${gameFrame==='wide'?'active':''}">Wide</button></div><a class="muted" href="${esc(gameHref('/'))}" target="_blank" rel="noopener">Open in a new tab</a></div><div class="${gameFrame==='phone'?'mobile-preview':'wide-preview'}"><iframe src="${esc(gameHref('/'))}" title="Game" allow="autoplay; fullscreen; gamepad"></iframe></div>`;document.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{gameFrame=b.dataset.frame;renderPreview()})}
function showSync(){const rows=data.syncStatus.sources.map(s=>`<div class="card"><strong>${esc(s.path)}</strong><p>Status: ${esc(s.status)}</p></div>`).join('');$('#modal').innerHTML=`<div class="panel"><h2>Source status</h2><p>Check the changed source files in the game.</p>${rows||'<p>No sources registered yet.</p>'}<button class="btn" id="cancel">Close</button></div>`;$('#modal').classList.remove('hidden');$('#cancel').onclick=()=>$('#modal').classList.add('hidden')}
const go=v=>{view=v;stopFlowTimer();flow=null;render()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#reload').onclick=load;$('#reviewSync').onclick=showSync;$('#dataChanged').onclick=load;$('#content').addEventListener('toggle',e=>{const box=e.target;if(box.matches?.('details[data-level]')){if(box.open)closedLevels.delete(box.dataset.level);else closedLevels.add(box.dataset.level)}},true);$('#content').addEventListener('click',e=>{const open=e.target.closest('[data-open-live]'),page=e.target.closest('[data-go]');if(page)go(page.dataset.go);else if(open)openLive(open);else if(e.target.closest('[data-close-live]'))closeLive()});load();setInterval(watchData,15000);window.addEventListener('focus',watchData);

const VERDICTS={good:'Good',okay:'Okay',weak:'Weak','cannot-tell':'Can’t tell'};
function reviewFound(){const catalogue=(data.catalogue?.sections||[]).reduce((n,c)=>n+c.items.length,0);return [{label:'Story',value:storyRows().join(' · ')||'Nothing mapped'},{label:'Characters',value:withVisual(data.characters.items)},{label:'Locations',value:withVisual(data.locations.items)},{label:'Assets',value:String(data.assets.items.length)},{label:'Pages',value:String(data.pages.items.length)},{label:'Catalogue items',value:String(catalogue)},{label:'Unmapped items',value:String(data.unmapped.items.length)}]}
function reviewPoint(p){const verdict=VERDICTS[p.verdict];return `<div class="review-point"><div class="review-head"><strong>${esc(p.topic)}</strong>${verdict?`<span class="chip verdict-${esc(p.verdict)}">${esc(verdict)}</span>`:''}</div>${p.note?`<p>${esc(p.note)}</p>`:''}${p.evidence?`<small class="muted asset-path">${esc(p.evidence)}</small>`:''}</div>`}
function renderReview(){const r=data.evaluation,points=Array.isArray(r?.points)?r.points:[],next=Array.isArray(r?.next)?r.next:[];const opinion=r?.error?noneYet('Could not read the review',r.error):r?.summary||points.length?`<section class="panel review-panel"><h2>Overall</h2>${r.summary?`<p>${esc(r.summary)}</p>`:''}<small class="muted">${[r.writtenOn?'Written '+r.writtenOn:'',r.basedOn?'Based on: '+r.basedOn:''].filter(Boolean).map(esc).join(' · ')}</small></section>${points.length?`<section class="panel review-panel">${points.map(reviewPoint).join('')}</section>`:''}${next.length?`<section class="panel review-panel"><h2>Fix first</h2><ol>${next.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>`:''}`:noneYet('No review yet','Ask your coding assistant to write gameflow/evaluation.json. AGENT_INSTRUCTIONS.md explains how.');$('#content').innerHTML=header('Review')+`<p class="muted">The AI’s own opinion of this game, not game content. Nothing in the game was changed because of it.</p>${opinion}${foundPanel()}`}

function renderSettings(){const files=data.kitFiles;const rows=[{label:'Kit version',value:data.kitVersion||'Unknown'},{label:'Platform files',value:!files?.checked?'Not checked':files.changed.length?`Changed: ${files.changed.join(', ')}`:'Unchanged'},{label:'Connection',value:data.connection?.state||'Unknown'},...(data.exported?[{label:'Saved copy made',value:new Date(data.exported.at).toLocaleString()}]:[])];$('#content').innerHTML=header('Settings')+`<section class="panel" style="margin-top:16px"><h2>${esc(data.project.name)}</h2>${data.project.description?`<p>${esc(data.project.description)}</p>`:''}${detailList(rows)}<p class="muted">Catalog is read-only. It shows the game’s own data and never changes it.</p></section>`}

function renderConnection(){
 $('#content').classList.remove('preview-content');$('#projectName').textContent=data.project.name;syncUI();
 const state=data.connection.state;const title=state==='error'?'Could not connect game data':state==='empty'?'Connected, but no scenes yet':'No game data connected';
 const message=state==='error'?data.connection.message:state==='empty'?'The game’s data was read, and it has no scenes yet. The Review page shows what was found.':'Ask your coding assistant to follow gameflow/INSTALL.md and connect this project.';
 $('#content').innerHTML=`<section class="panel" style="margin-top:16px"><h2>${title}</h2><p class="muted">${esc(message)}</p></section>`;
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
}

function withVisual(items){const seen=items.filter(visualOf).length;return `${items.length}${items.length?` · ${seen} with a picture`:''}`}
function foundPanel(){return `<section class="panel review-panel"><h2>What Catalog found</h2><p class="muted">Counted by code from the mapping, so you can check it.</p>${detailList(reviewFound())}${assetItems().length?`<p class="muted found-assets">Asset check: <span id="assetSummary">${assetSummary()}</span></p>`:''}</section>`}

// Overview, plan and design: the assistant's own write-ups, always labelled, beside what code counted.
const STATUSES={done:'Done','in-progress':'In progress',planned:'Planned',blocked:'Blocked',unknown:'Not clear'};
const textOf=v=>typeof v==='string'&&v.trim()?v:'';
const listOf=v=>Array.isArray(v)?v.filter(x=>x&&typeof x==='object'):[];
const blockOf=v=>typeof v==='string'?{text:v}:v&&typeof v==='object'?v:{};
function origin(x,inline=false){const cls=`origin${inline?' inline':''}`;return x?.by==='game'?`<small class="${cls}">From the game${textOf(x.source)?' · '+esc(x.source):''}</small>`:inline?'':`<small class="${cls}">AI’s reading${textOf(x?.source)?' · from '+esc(x.source):''}</small>`}
function notWritten(what){return data.catalogError?noneYet('Could not read catalog.json',data.catalogError):noneYet('Not written yet',`Ask your coding assistant to write the ${what} in gameflow/catalog.json. AGENT_INSTRUCTIONS.md explains how.`)}
function writeupMeta(w){return `<p class="muted writeup-meta">${w.from==='mapping'?'Read live from the game by the mapping.':`Written by the AI in gameflow/catalog.json${textOf(w.writtenOn)?' on '+esc(w.writtenOn):''}. It does not update by itself.`}</p>`}
function writeupSection(x,title){const points=(Array.isArray(x.points)?x.points:[]).filter(textOf);return `<article class="reading-card writeup"><h3>${esc(title)}</h3>${textOf(x.text)?prose(x.text):''}${points.length?`<ul>${points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}${origin(x)}</article>`}
function writeupBody(w,standard=[],middle=''){const summary=blockOf(w.summary),facts=listOf(w.facts).filter(f=>textOf(f.label)&&textOf(f.value)),rank=x=>{const i=standard.findIndex(s=>s.id===x.id);return i<0?standard.length:i};const sections=listOf(w.sections).map((x,i)=>({x,i})).sort((a,b)=>rank(a.x)-rank(b.x)||a.i-b.i).map(({x})=>x);
 return `${textOf(summary.text)?`<section class="panel writeup">${prose(summary.text)}${origin(summary)}</section>`:''}${middle}${facts.length?`<section class="panel writeup"><dl class="detail-list">${facts.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(f.value)}${origin(f,true)}</dd></div>`).join('')}</dl>${facts.every(f=>f.by==='game')?'':'<small class="origin">AI’s reading, except where it says From the game</small>'}</section>`:''}${sections.map(x=>writeupSection(x,textOf(x.title)||standard.find(s=>s.id===x.id)?.title||tidy(String(x.id||'Notes')))).join('')}`}
function glance(){const audio=assetItems().filter(a=>a.type==='audio').length,more=(data.catalogue?.sections||[]).filter(c=>!c.browser).reduce((n,c)=>n+c.items.length,0),missing=(data.unmapped?.items||[]).filter(u=>u.kind==='missing-asset').length+failedAssets().length,items=planItems(),done=items.filter(x=>x.status==='done').length;
 const rows=[['staging','Story',storyRows().join(' · ')||'None mapped'],['characters','Characters',data.characters.items.length],['locations','Locations',data.locations.items.length],['assets','Assets',assetItems().length],['sound','Sound files',audio],['catalogue','More from the game',more],['pages','Pages',gamePages().length],['plan','Plan',items.length?`${done} of ${items.length} done`:'No plan found'],['unmapped','Missing files',missing]];
 return `<div class="glance">${rows.map(([v,label,value])=>`<button class="glance-item" data-go="${v}"><small class="muted">${esc(label)}</small><strong>${esc(value)}</strong></button>`).join('')}</div>`}
function renderOverview(){const w=data.overview,p=data.project;$('#content').innerHTML=header('Overview')+`<section class="panel overview-head"><h2>${esc(p.name||'Untitled')}</h2>${p.description?`<p>${esc(p.description)}</p>`:''}</section>${glance()}${w?writeupMeta(w)+writeupBody(w):notWritten('overview')}${catalogueFor('overview')}`}
function planItems(){return listOf(data.plan?.items).filter(x=>textOf(x.title))}
const statusOf=x=>STATUSES[x.status]?x.status:'unknown';
function progressBar(items){const counts=Object.keys(STATUSES).map(k=>[k,items.filter(x=>statusOf(x)===k).length]).filter(([,n])=>n),text=counts.map(([k,n])=>`${n} ${STATUSES[k].toLowerCase()}`).join(' · ');return `<div class="progress-bar" role="img" aria-label="${esc(text)}">${counts.map(([k,n])=>`<span class="bar-${k}" style="flex:${n}"></span>`).join('')}</div><p class="muted">${esc(text)}</p>`}
function planRow(x){const s=statusOf(x);return `<div class="review-point"><div class="review-head"><strong>${esc(x.title)}</strong><span class="chip plan-${s}">${esc(STATUSES[s])}</span></div>${textOf(x.note)?`<p>${esc(x.note)}</p>`:''}${origin(x)}</div>`}
function renderPlan(){const w=data.plan,items=planItems(),areas=[...new Set(items.map(x=>textOf(x.area)||'Other'))],inArea=a=>items.filter(x=>(textOf(x.area)||'Other')===a);
 const list=items.length?`<section class="panel review-panel"><h2>Progress</h2>${progressBar(items)}</section>${areas.map(a=>`<section class="panel review-panel"><h2>${esc(a)} <small class="muted">${inArea(a).length}</small></h2>${inArea(a).map(planRow).join('')}</section>`).join('')}`:w?noneYet('No plan items','No to-do list, roadmap or task list was found in the game.'):'';
 $('#content').innerHTML=header('Plan and progress')+(w?writeupMeta(w)+writeupBody(w,[],list):notWritten('plan'))+catalogueFor('plan')+foundPanel()}
function renderDesign(){const w=data.design,std=data.standardDesign||[],absent=std.filter(x=>!listOf(w?.sections).some(s=>s.id===x.id));$('#content').innerHTML=header('Game design')+(w?writeupMeta(w)+writeupBody(w,std):notWritten('game design'))+catalogueFor('design')+(w&&absent.length?`<p class="muted catalogue-absent">Not found for this game: ${absent.map(x=>esc(x.title)).join(', ')}</p>`:'')}

// Every page the game has, as links. Pages without a route are listed with their source file.
function gamePages(){return [...(data.pages?.items||[]),...(data.ui?.mocks||[]).map(m=>({id:'mock/'+m.id,name:m.name||m.id,kind:'UI mock',route:m.previewSrc,source:m.target,status:m.status}))]}
function pageRow(p){const open=safeRoute(p.route);return `${open?`<a class="page-link" href="${esc(gameHref(p.route))}" target="_blank" rel="noopener">`:'<div class="page-link no-route">'}<span><strong>${esc(p.name)}</strong><small class="muted">${esc(open?p.route:'No link')}${p.source?' · '+esc(p.source):''}</small></span>${p.status?`<span class="chip">${esc(p.status)}</span>`:''}${open?'<span class="page-arrow" aria-hidden="true">↗</span></a>':'</div>'}`}
function renderPages(){const all=gamePages(),kinds=[...new Set(all.map(p=>p.kind))];if(!['all',...kinds].includes(pageFilter))pageFilter='all';const shown=kinds.filter(k=>pageFilter==='all'||k===pageFilter);
 const none=data.reported?.pages||all.length?noneYet('No pages','The assistant reported no pages in this game.'):noneYet('No report yet','This connection has not reported its pages. Ask your coding assistant to add them.');
 $('#content').innerHTML=header('Pages',all.length)+(all.length?`<p class="muted">Every page in the game. Each link opens the real page in a new tab.</p>${kinds.length>1?`<div class="asset-filters">${['all',...kinds].map(k=>`<button class="${k===pageFilter?'active':''}" data-page-filter="${esc(k)}">${esc(k==='all'?'All':k)} <small>${k==='all'?all.length:all.filter(p=>p.kind===k).length}</small></button>`).join('')}</div>`:''}${shown.map(k=>`<section class="asset-group"><h3 class="unmapped-source">${esc(tidy(String(k)))} <small class="muted">${all.filter(p=>p.kind===k).length}</small></h3><div class="page-list">${all.filter(p=>p.kind===k).map(pageRow).join('')}</div></section>`).join('')}`:none);
 document.querySelectorAll('[data-page-filter]').forEach(b=>b.onclick=()=>{pageFilter=b.dataset.pageFilter;renderPages()})}

// Branding sits at the top of Assets: the app icon, splash screen and logo the game uses, then design tryouts.
const BRAND={'app-icon':'App icon',splash:'Splash screen',logo:'Logo',tryout:'Tryouts'};
function brandSlot(key){const list=assetItems().filter(a=>a.brand===key);return `<div class="brand-slot"><h4>${BRAND[key]}${list.length>1?` <small class="muted">${list.length}</small>`:''}</h4>${list.length?`<div class="grid">${list.map(assetCard).join('')}</div>`:'<div class="asset-file brand-missing">Not found in the game</div>'}</div>`}
function brandingSection(){const tryouts=assetItems().filter(a=>a.brand==='tryout');return `<section class="asset-group brand-group"><div class="brand-slots">${['app-icon','splash','logo'].map(brandSlot).join('')}</div>${tryouts.length?brandSlot('tryout'):''}</section>`}
